<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Project;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Str;
use Tests\TestCase;
class GharTest extends TestCase {
 use RefreshDatabase;
 private function project(User $u):Project{$p=new Project(['name'=>'Test Home','location'=>'Kathmandu','budget_paisa'=>100000]);$p->user_id=$u->id;$p->save();return $p;}
 private function material():array{return ['name'=>'Cement','supplier'=>'Local supplier','quantity'=>'10.500','rate'=>'950.25','unit'=>'bag','recorded_on'=>'2026-10-13'];}
 public function test_api_requires_authentication():void{$this->getJson('/api/projects')->assertUnauthorized();$this->postJson('/api/projects',[])->assertUnauthorized();}
 public function test_owner_can_create_project_with_exact_budget():void{$u=User::factory()->create();$this->actingAs($u)->postJson('/api/projects',['name'=>'New house','location'=>'Patan','budget'=>'1000.01'])->assertCreated()->assertJsonPath('budget_paisa',100001);}
 public function test_list_is_scoped_to_owner():void{$a=User::factory()->create();$b=User::factory()->create();$p=$this->project($a);$this->project($b);$this->actingAs($a)->getJson('/api/projects')->assertOk()->assertJsonCount(1)->assertJsonPath('0.id',$p->id);}
 public function test_cross_project_reads_and_writes_are_denied():void{$a=User::factory()->create();$b=User::factory()->create();$p=$this->project($a);$this->actingAs($b)->getJson('/api/projects/'.$p->id)->assertNotFound();$this->postJson('/api/projects/'.$p->id.'/materials',$this->material())->assertNotFound();$this->postJson('/api/projects/'.$p->id.'/logs',[])->assertNotFound();$this->postJson('/api/projects/'.$p->id.'/consultations',[])->assertNotFound();}
 public function test_material_total_is_exact():void{$u=User::factory()->create();$p=$this->project($u);$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/materials',$this->material())->assertCreated()->assertJsonPath('total_paisa',997763);$this->getJson('/api/projects/'.$p->id)->assertJsonPath('material_total_paisa',997763);}
 public function test_invalid_material_values_are_rejected():void{$u=User::factory()->create();$p=$this->project($u);foreach(['-1','0','1e3','0.0001'] as $q)$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/materials',[...$this->material(),'quantity'=>$q])->assertUnprocessable();}
 public function test_material_unit_is_allowlisted():void{$u=User::factory()->create();$p=$this->project($u);$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/materials',[...$this->material(),'unit'=>'evil'])->assertUnprocessable();}
 public function test_owner_cannot_be_changed_via_mass_assignment():void{$a=User::factory()->create();$b=User::factory()->create();$this->actingAs($a)->postJson('/api/projects',['name'=>'Home','location'=>'Patan','budget'=>'1','user_id'=>$b->id])->assertCreated();$this->assertDatabaseHas('projects',['user_id'=>$a->id]);$this->assertDatabaseMissing('projects',['user_id'=>$b->id]);}
 public function test_sql_injection_payload_is_plain_data():void{$u=User::factory()->create();$name="Home'); DROP TABLE users; --";$this->actingAs($u)->postJson('/api/projects',['name'=>$name,'location'=>'Patan','budget'=>'1'])->assertCreated();$this->assertDatabaseHas('projects',['name'=>$name]);$this->assertDatabaseCount('users',1);}
 public function test_route_id_injection_cannot_read_projects():void{$u=User::factory()->create();$this->project($u);$this->actingAs($u)->getJson('/api/projects/1%20OR%201=1')->assertNotFound();}
 public function test_injection_login_does_not_authenticate():void{$this->postJson('/login',['email'=>"' OR 1=1 --",'password'=>'anything'])->assertUnprocessable();$this->assertGuest();}
 public function test_duplicate_offline_logs_are_idempotent():void{$u=User::factory()->create();$p=$this->project($u);$v=['client_uuid'=>(string)Str::uuid(),'recorded_on'=>'2026-10-13','notes'=>'Foundation complete'];$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/logs',$v)->assertCreated();$this->postJson('/api/projects/'.$p->id.'/logs',$v)->assertOk();$this->assertDatabaseCount('daily_logs',1);}
 public function test_offline_uuid_content_conflicts_are_reported():void{$u=User::factory()->create();$p=$this->project($u);$v=['client_uuid'=>(string)Str::uuid(),'recorded_on'=>'2026-10-13','notes'=>'Original'];$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/logs',$v)->assertCreated();$this->postJson('/api/projects/'.$p->id.'/logs',[...$v,'notes'=>'Changed'])->assertConflict();}
 public function test_log_requires_valid_uuid():void{$u=User::factory()->create();$p=$this->project($u);$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/logs',['client_uuid'=>'bad','recorded_on'=>'2026-10-13','notes'=>'Hello'])->assertUnprocessable();}
 public function test_future_consultation_can_be_requested():void{$u=User::factory()->create();$p=$this->project($u);$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/consultations',['topic'=>'Floor plan review','mode'=>'video','requested_at'=>now()->addDays(3)->toIso8601String()])->assertCreated()->assertJsonPath('status','requested');}
 public function test_consultation_time_is_normalized_to_utc():void{$u=User::factory()->create();$p=$this->project($u);$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/consultations',['topic'=>'Review','mode'=>'video','requested_at'=>'2090-01-01T12:00:00+05:45'])->assertCreated()->assertJsonPath('requested_at','2090-01-01T06:15:00+00:00');}
 public function test_past_consultation_is_rejected():void{$u=User::factory()->create();$p=$this->project($u);$this->actingAs($u)->postJson('/api/projects/'.$p->id.'/consultations',['topic'=>'Review','mode'=>'video','requested_at'=>'2000-01-01'])->assertUnprocessable();}
 public function test_credentials_issue_revocable_mobile_token():void{$u=User::factory()->create(['password'=>'TestPassword123!']);$v=$this->postJson('/api/token',['email'=>$u->email,'password'=>'TestPassword123!','device_name'=>'Flutter tests'])->assertOk()->json();$this->withToken($v['token'])->getJson('/api/me')->assertOk()->assertJsonMissingPath('password');$this->withToken($v['token'])->deleteJson('/api/token')->assertNoContent();$this->assertDatabaseCount('personal_access_tokens',0);}
 public function test_login_rate_limit():void{for($i=0;$i<5;$i++)$this->postJson('/login',['email'=>'limit@test.com','password'=>'bad'])->assertUnprocessable();$this->postJson('/login',['email'=>'limit@test.com','password'=>'bad'])->assertStatus(429);}
 public function test_security_headers_present():void{$this->get('/')->assertOk()->assertHeader('X-Content-Type-Options','nosniff')->assertHeader('X-Frame-Options','DENY');}
}
